import json,re,subprocess,sys
def collect(ports):
    if not isinstance(ports,list) or not ports or any(type(p)is not int or not 1024<=p<=65535 for p in ports) or len(set(ports))!=len(ports):raise ValueError('unique numeric high ports required')
    interfaces=json.loads(subprocess.check_output(['ip','-s','-j','link','show','dev','lo'],text=True,timeout=2))
    counters=interfaces[0].get('stats64',interfaces[0].get('stats'))
    raw=subprocess.check_output(['ss','-t','-i','-n','-H','-p'],text=True,timeout=2)
    records=[];current=None
    for line in raw.splitlines():
        if line and not line[0].isspace():
            current=None;parts=line.split()
            if len(parts)<5 or parts[0]!='ESTAB':continue
            local,peer=parts[3],parts[4]
            if not local.startswith('127.0.0.1:') or not peer.startswith('127.0.0.1:'):continue
            local_port=int(local.rsplit(':',1)[1]);peer_port=int(peer.rsplit(':',1)[1])
            pid=re.search(r'\bpid=(\d+)',line)
            if peer_port not in ports or not pid:continue
            current={'local_port':local_port,'peer_port':peer_port,'pid':int(pid.group(1))}
        elif current is not None:
            sent=re.search(r'\bbytes_sent:(\d+)',line);received=re.search(r'\bbytes_received:(\d+)',line)
            if sent and received:
                current.update(bytes_sent=int(sent.group(1)),bytes_received=int(received.group(1)))
                records.append(current);current=None
    return {'interface':'lo','rx_bytes':int(counters['rx']['bytes']),'tx_bytes':int(counters['tx']['bytes']),
            'connections':sorted(records,key=lambda r:(r['peer_port'],r['local_port'],r['pid']))}
if __name__=='__main__':
    try:result=collect(json.load(open(sys.argv[1]))['peer_ports'])
    except (ValueError,TypeError,KeyError,IndexError,OSError,subprocess.SubprocessError):raise SystemExit(2)
    print(json.dumps(result,sort_keys=True))
```

ss条目按连接四元组关联PID，后续缩进行提供内核TCP_INFO字节。只读同一用户所属客户端，无法看见其他用户PID时不能猜测。网卡统计包括协议头和其他连接，不能用它替代进程字节。

原理说明：
先固定时间窗口和接口，区分物理出口与veth/bridge重复计数；查看字节率、包率、丢包及连接分布，再按地址端口关联进程、应用请求量与近期批任务。需要抓包时限制对象、时长和载荷，不能因流量大就断定攻击。验收异常来源、预期业务峰值及受控缓解后的错误率，不盲目封禁所有来源。

