import json,os,pathlib,socket,subprocess,sys,threading,time,secrets
root=pathlib.Path.cwd();servers=[];threads=[];workers=[];stop=threading.Event()
def serve(listener):
    listener.settimeout(.2)
    while not stop.is_set():
        try:conn,_=listener.accept()
        except socket.timeout:continue
        with conn:
            conn.settimeout(.2);pending=b''
            while not stop.is_set():
                try:data=conn.recv(65536)
                except socket.timeout:continue
                if not data:break
                pending+=data
                # Requests are length-prefixed; one response byte per complete payload.
                while len(pending)>=4 and len(pending)>=4+int.from_bytes(pending[:4],'big'):
                    size=int.from_bytes(pending[:4],'big');pending=pending[4+size:];conn.sendall(b'K')
WORKER=r"""import socket,sys,json
s=socket.create_connection(('127.0.0.1',int(sys.argv[1])));s.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,1)
print(json.dumps({'port':s.getsockname()[1]}),flush=True)
for line in sys.stdin:
 n=int(line);s.sendall(n.to_bytes(4,'big')+b'x'*n);assert s.recv(1)==b'K';print('ok',flush=True)
s.close()
"""
try:
    ports=[]
    for _ in range(3):
        listener=socket.socket();listener.bind(('127.0.0.1',0));listener.listen();servers.append(listener);ports.append(listener.getsockname()[1])
        thread=threading.Thread(target=serve,args=(listener,));thread.start();threads.append(thread)
        proc=subprocess.Popen([sys.executable,'-c',WORKER,str(ports[-1])],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        local=json.loads(proc.stdout.readline())['port'];workers.append((proc,local))
    def send(index,size):
        proc,_=workers[index];proc.stdin.write(str(size)+'\n');proc.stdin.flush();assert proc.stdout.readline()=='ok\n'
    initial=[700+secrets.randbelow(500),900+secrets.randbelow(500),1200]
    for i,size in enumerate(initial):send(i,size)
    (root/'peers.json').write_text(json.dumps({'peer_ports':ports[:2]}))
    def read():
        p=subprocess.run([sys.executable,'collect.py','peers.json'],capture_output=True,text=True,timeout=4)
        assert p.returncode==0,p.stderr;value=json.loads(p.stdout)
        assert set(value)=={'interface','rx_bytes','tx_bytes','connections'} and value['interface']=='lo'
        assert type(value['rx_bytes']) is int and type(value['tx_bytes']) is int
        rows=value['connections'];assert len(rows)==2,'must select destination peers, not all loopback sockets or server direction'
        index={row['peer_port']:row for row in rows};assert set(index)==set(ports[:2])
        for i in range(2):
            row=index[ports[i]];assert set(row)=={'local_port','peer_port','pid','bytes_sent','bytes_received'}
            assert row['pid']==workers[i][0].pid and row['local_port']==workers[i][1],'socket-to-process attribution mismatch'
            assert type(row['bytes_sent']) is int and type(row['bytes_received']) is int
        return value,index
    before,first=read()
    for i in range(2):assert first[ports[i]]['bytes_sent']==initial[i]+4 and first[ports[i]]['bytes_received']==1
    delta=[4096+secrets.randbelow(2048),8192+secrets.randbelow(2048)]
    for i,size in enumerate(delta):send(i,size)
    send(2,20000) # Excluded socket changes the interface aggregate too.
    after,last=read()
    for i in range(2):
        assert last[ports[i]]['bytes_sent']-first[ports[i]]['bytes_sent']==delta[i]+4
        assert last[ports[i]]['bytes_received']-first[ports[i]]['bytes_received']==1
    assert after['tx_bytes']>before['tx_bytes'] and after['rx_bytes']>before['rx_bytes']
    assert after['tx_bytes']-before['tx_bytes']>sum(delta),'interface total includes other sockets and protocol bytes'
    for bad in ([],[ports[0],ports[0]],[True],['12345'],[80],[{}],[[12345]],None):
        (root/'peers.json').write_text(json.dumps({'peer_ports':bad}))
        p=subprocess.run([sys.executable,'collect.py','peers.json'],capture_output=True,text=True,timeout=4)
        assert p.returncode==2 and not p.stdout.strip(),'invalid scope must not silently widen collection'
finally:
    for proc,_ in workers:
        if proc.stdin:proc.stdin.close()
        try:proc.wait(timeout=2)
        except subprocess.TimeoutExpired:proc.kill();proc.wait()
        if proc.stdout:proc.stdout.close()
        if proc.stderr:proc.stderr.close()
    stop.set()
    for thread in threads:thread.join(2);assert not thread.is_alive()
    for listener in servers:listener.close()
